arguments.command:
POD=$(kubectl get pod -n social-network -l service=nginx-thrift -o jsonpath='{.items[0].metadata.name}'); kubectl exec -n social-network $POD -- sh -c 'curl -s -o /dev/null -w "register: HTTP %{http_code}
" -X POST "http://localhost:8080/wrk2-api/user/register" -d "first_name=Test&last_name=User&username=testuser$$&password=test123"; curl -s -o /dev/null -w "home-timeline: HTTP %{http_code}
" "http://localhost:8080/wrk2-api/home-timeline/read?user_id=1&start=0&stop=10"; curl -s -o /dev/null -w "user-timeline: HTTP %{http_code}
" "http://localhost:8080/wrk2-api/user-timeline/read?user_id=1&start=0&stop=10"' 2>/dev/null

POD=$(kubectl get pod -n social-network -l service=nginx-thrift -o jsonpath='{.items[0].metadata.name}'); kubectl exec -n social-network $POD -c nginx-thrift -- sh -c 'curl -s -o /dev/null -w "register: HTTP %{http_code}
" -X POST "http://localhost:8080/wrk2-api/user/register" -d "first_name=Test&last_name=User&username=testuser1&password=test123&user_id=5001"; curl -s -o /dev/null -w "compose: HTTP %{http_code}
" -X POST "http://localhost:8080/wrk2-api/post/compose" -d "username=testuser1&user_id=5001&text=hello world&post_type=0"; curl -s -o /dev/null -w "follow: HTTP %{http_code}
" -X POST "http://localhost:8080/wrk2-api/social-graph/follow" -d "user_id=5001&followee_id=1"; curl -s -o /dev/null -w "home-timeline: HTTP %{http_code}
" "http://localhost:8080/wrk2-api/home-timeline/read?user_id=5001&start=0&stop=10"'
